import { GoogleGenAI, Type, Modality } from "@google/genai";

export const isAIConfigured = () => {
  return !!process.env.API_KEY && process.env.API_KEY.length > 10;
};

const throttle = async () => {
  // Use a module-level variable for throttling
  if (!(window as any)._lastRequestTimestamp) (window as any)._lastRequestTimestamp = 0;
  const now = Date.now();
  const timeSinceLast = now - (window as any)._lastRequestTimestamp;
  if (timeSinceLast < 1500) {
    await new Promise(resolve => setTimeout(resolve, 1500 - timeSinceLast));
  }
  (window as any)._lastRequestTimestamp = Date.now();
};

const parseAIResponse = (text: any) => {
  if (!text || typeof text !== 'string') return null;
  try {
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanText);
  } catch (e) {
    console.error("Failed to parse AI JSON response", e);
    return null;
  }
};

export const generateLessonContent = async (subject: string, topic: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const isPython = subject.toLowerCase().includes('python');
  const isWeb = subject.toLowerCase().includes('web');
  const isData = subject.toLowerCase().includes('data');

  let systemInstruction = "You are the Head Tutor at MindGrid CramZone. You specialize in the Nigerian JAMB/WAEC Syllabus. Your explanations are clear, concise, and focused on helping students score high in UTME/WASSCE.";
  let localContextPrompt = "A section explaining how this topic specifically appears in JAMB/WAEC, common traps for Nigerian students, or local mnemonics.";

  if (isPython) {
    systemInstruction = "You are the Senior Python Engineer at MindGrid. You specialize in teaching modern Python (3.12+). You use type hints, PEP 8 standards, and high-performance patterns.";
    localContextPrompt = "A section named 'Naija Tech Career' explaining how this specific Python skill is used in the local ecosystem.";
  } else if (isWeb) {
    systemInstruction = "You are the Lead Web Architect at MindGrid. You teach modern Full-Stack Development (React, Node, Tailwind).";
    localContextPrompt = "A section named 'Naija Web Ecosystem' explaining how this skill applies to the Nigerian market.";
  } else if (isData) {
    systemInstruction = "You are the Lead Data Scientist at MindGrid Analytics. You teach data analysis, statistics, and business intelligence.";
    localContextPrompt = "A section named 'Naija Data Insights' explaining how this analysis skill is valued in Nigeria.";
  }

  const prompt = `Generate a structured educational lesson for Category/Subject: ${subject} and Topic: ${topic}. 
  Return a JSON object with: theory (Markdown), examples (Markdown), naijaContext (Markdown), and quiz (3 MCQs).`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            theory: { type: Type.STRING },
            examples: { type: Type.STRING },
            naijaContext: { type: Type.STRING },
            quiz: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  answer: { type: Type.INTEGER },
                  explanation: { type: Type.STRING }
                },
                required: ["question", "options", "answer", "explanation"]
              }
            }
          },
          required: ["theory", "examples", "naijaContext", "quiz"]
        }
      }
    });

    return parseAIResponse(response.text);
  } catch (error) {
    console.error("Lesson Generation Error:", error);
    return null;
  }
};

export const fetchCourseRequirements = async (course: string, university: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `Find the 2024/2025 admission requirements for "${course}" at "${university}" in Nigeria. Include JAMB combination, O-Level requirements, and cutoff mark.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are an expert Admissions Consultant for Nigerian Universities. Always cite sources from official portals.",
      },
    });

    const text = response.text || "No data found.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];

    return { text, sources };
  } catch (error) {
    console.error("Course Finder Error:", error);
    throw error;
  }
};

export const generateFullArticle = async (topic?: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = topic 
    ? `Write a 600-word academic guide for Nigerian students on: "${topic}". Return as JSON.`
    : `Choose a random trending academic/tech topic for Nigerian students. Return as JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        systemInstruction: "You are the Lead Editor of MindGrid Library. Return ONLY valid JSON.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            excerpt: { type: Type.STRING },
            content: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "excerpt", "content", "category"]
        }
      }
    });

    return parseAIResponse(response.text);
  } catch (error) {
    return null;
  }
};

export const generateStudyHelp = async (query: string, useSearch: boolean = false) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const config: any = {
      systemInstruction: `You are MindGrid AI, an academic mentor for Nigerians. Grounding: JAMB, WAEC, NUC.`,
      temperature: 0.8,
    };
    if (useSearch) config.tools = [{ googleSearch: {} }];
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: query }] }],
      config: config,
    });
    const text = response.text || "Failed to generate response.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];
    return { text, sources };
  } catch (error: any) { throw error; }
};

export const fetchRealtimeNews = async (category: string) => {
  if (!isAIConfigured()) return null;
  await throttle();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const searchCategory = category === 'All' ? 'Nigerian Education News' : `Nigerian ${category} news`;
  const prompt = `Find 3 recent student updates for: "${searchCategory}". Format as a JSON array of objects with title, excerpt, date, url.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        // Rule: Search grounding responses may not be JSON. We request JSON in the prompt but don't force mimeType.
      },
    });
    // Attempt parsing. If fails, returning mock/null is handled by caller.
    return parseAIResponse(response.text);
  } catch (error) { return null; }
};

export const generateAISchedule = async (goal: string) => {
  if (!isAIConfigured()) return null;
  await throttle();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: `Generate a 7-day study plan for: "${goal}". Return as JSON.` }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              day: { type: Type.STRING },
              sessions: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { subject: { type: Type.STRING }, topic: { type: Type.STRING } } } }
            }
          }
        }
      },
    });
    return parseAIResponse(response.text);
  } catch (error) { return null; }
};

export const textToSpeech = async (text: string) => {
  if (!isAIConfigured()) return null;
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text.substring(0, 1000) }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (e) { return null; }
};

import React, { useState, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { generateStudyHelp, isAIConfigured, textToSpeech } from '../services/geminiService';

interface Message {
  role: 'user' | 'assistant';
  text: string;
  sources?: { title: string, uri: string }[];
  audioBase64?: string;
}

const AIHub: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState<number | null>(null);
  const [useSearch, setUseSearch] = useState(true);
  const [cooldown, setCooldown] = useState(0);
  const [configError, setConfigError] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isAIConfigured()) {
      setConfigError(true);
    }

    const saved = sessionStorage.getItem('mindgrid_chat_v4');
    if (saved) {
      setMessages(JSON.parse(saved));
    } else {
      setMessages([{ 
        role: 'assistant', 
        text: "Welcome back! I am MindGrid AI, your dedicated academic tutor. How can I help you excel in your studies today?" 
      }]);
    }
  }, []);

  useEffect(() => {
    sessionStorage.setItem('mindgrid_chat_v4', JSON.stringify(messages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [cooldown]);

  const handleSend = async () => {
    if (!input.trim() || isLoading || cooldown > 0 || configError) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsLoading(true);

    try {
      const result = await generateStudyHelp(userMsg, useSearch);
      setMessages(prev => [...prev, { 
        role: 'assistant', 
        text: result.text, 
        sources: result.sources 
      }]);
      setCooldown(3); 
    } catch (error: any) {
      setMessages(prev => [...prev, { 
        role: 'assistant', 
        text: "I'm having trouble connecting to my academic database. Please ensure your internet connection is stable and try again." 
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const playAudio = async (text: string, index: number) => {
    if (isSpeaking === index) {
      setIsSpeaking(null);
      return;
    }

    setIsSpeaking(index);
    try {
      const base64 = await textToSpeech(text);
      if (base64) {
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const binaryString = atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }

        // Ensure even byte length for Int16 conversion
        const pcmData = new Int16Array(bytes.buffer.slice(0, len - (len % 2)));
        const buffer = audioCtx.createBuffer(1, pcmData.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < pcmData.length; i++) {
          channelData[i] = pcmData[i] / 32768.0;
        }

        const source = audioCtx.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtx.destination);
        source.onended = () => setIsSpeaking(null);
        source.start();
      }
    } catch (err) {
      console.error(err);
      setIsSpeaking(null);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 flex flex-col h-[85vh]">
      {configError && (
        <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl text-red-800 flex items-center gap-4 shadow-sm animate-in">
          <i className="fas fa-exclamation-triangle text-2xl"></i>
          <div>
            <p className="font-black text-sm uppercase tracking-widest">Configuration Warning</p>
            <p className="text-sm">The AI service is unavailable. Check your <strong>API_KEY</strong> configuration.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] shadow-2xl flex-grow flex flex-col overflow-hidden border border-slate-100">
        <div className="bg-slate-900 p-6 text-white flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="bg-blue-600 p-3 rounded-2xl shadow-lg shadow-blue-500/30">
              <i className="fas fa-graduation-cap text-xl"></i>
            </div>
            <div>
              <h1 className="font-black text-lg tracking-tight">MindGrid <span className="text-blue-500">Tutor</span></h1>
              <div className="flex items-center gap-2">
                <span className="w-2 h-2 bg-blue-400 rounded-full animate-pulse"></span>
                <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Academic Mode</span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button 
              onClick={() => setUseSearch(!useSearch)}
              className={`text-[10px] font-black px-4 py-2 rounded-xl uppercase transition-all flex items-center gap-2 ${useSearch ? 'bg-blue-600 text-white shadow-lg' : 'bg-white/10 text-slate-400'}`}
            >
              <i className="fas fa-globe"></i> {useSearch ? 'Search On' : 'Search Off'}
            </button>
            <button 
              onClick={() => {
                sessionStorage.removeItem('mindgrid_chat_v4');
                setMessages([{ role: 'assistant', text: "Chat history cleared. How can I help you today?" }]);
              }}
              className="text-[10px] font-black bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl uppercase transition-colors"
            >
              Reset
            </button>
          </div>
        </div>

        <div className="flex-grow overflow-y-auto p-8 space-y-8 bg-slate-50/30">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start animate-in'}`}>
              <div className={`max-w-[85%] p-6 rounded-3xl shadow-sm leading-relaxed relative group ${
                msg.role === 'user' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'
              }`}>
                <div className={`prose prose-sm md:prose-base max-w-none ${msg.role === 'user' ? 'prose-invert text-white' : 'text-slate-800'}`}>
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>
                    {msg.text}
                  </ReactMarkdown>
                </div>

                {msg.role === 'assistant' && (
                  <button 
                    onClick={() => playAudio(msg.text, idx)}
                    className="absolute -right-4 -bottom-4 bg-white shadow-xl w-10 h-10 rounded-2xl flex items-center justify-center text-blue-600 hover:scale-110 transition-transform border border-slate-100 z-10"
                    title="Read aloud"
                  >
                    <i className={`fas ${isSpeaking === index ? 'fa-pause text-xs' : 'fa-volume-up text-sm'}`}></i>
                  </button>
                )}
              </div>

              {msg.sources && msg.sources.length > 0 && (
                <div className="mt-4 flex flex-wrap gap-2">
                  <span className="text-[10px] text-slate-400 font-bold uppercase py-1 px-1">Sources:</span>
                  {msg.sources.map((s, i) => (
                    <a key={i} href={s.uri} target="_blank" className="text-[10px] font-black text-blue-700 bg-blue-50 px-3 py-1.5 rounded-xl border border-blue-100 hover:bg-blue-100 transition-all flex items-center gap-1">
                      <i className="fas fa-link text-[8px]"></i> {s.title}
                    </a>
                  ))}
                </div>
              )}
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white px-6 py-4 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4">
                <div className="flex gap-1.5">
                  <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-100"></div>
                  <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-200"></div>
                </div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Researching...</span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-8 bg-white border-t border-slate-100">
          <div className="flex gap-4">
            <input
              type="text"
              placeholder={cooldown > 0 ? `Please wait ${cooldown}s...` : "Ask about JAMB Syllabus, Physics, or Career paths..."}
              disabled={cooldown > 0 || configError}
              className="flex-grow bg-slate-50 border border-slate-200 rounded-[1.5rem] px-6 py-5 outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 disabled:opacity-50 font-medium transition-all text-slate-700 shadow-inner"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button
              onClick={handleSend}
              disabled={isLoading || !input.trim() || cooldown > 0 || configError}
              className="bg-slate-950 text-white w-16 h-16 rounded-[1.5rem] flex items-center justify-center hover:bg-blue-600 transition-all shadow-xl disabled:opacity-50 active:scale-95 group"
            >
              <i className="fas fa-paper-plane text-xl group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform"></i>
            </button>
          </div>
          <div className="flex items-center justify-center gap-6 mt-6">
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Verified Academic AI</p>
            <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Privacy Shield Active</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIHub;

