import React, { useState, useRef, useEffect } from 'react';
import { useToast } from '../context/ToastContext';
import { Share2, Link as LinkIcon, Twitter, Facebook, MessageCircle, X as CloseIcon } from 'lucide-react';

interface ShareButtonProps {
  title: string;
  text: string;
  url?: string;
  className?: string;
  variant?: 'icon' | 'full' | 'outline' | 'ghost';
  iconOnly?: boolean;
}

const ShareButton: React.FC<ShareButtonProps> = ({ 
  title, 
  text, 
  url = window.location.href, 
  className = '', 
  variant = 'icon',
  iconOnly = false
}) => {
  const { showToast } = useToast();
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    if (showMenu) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showMenu]);

  const handleShareTrigger = async () => {
    // If native share is available and not on a desktop, use it
    if (navigator.share && /iPhone|iPad|iPod|Android/i.test(navigator.userAgent)) {
      try {
        await navigator.share({ title, text, url });
        return;
      } catch (e) {
        // Fallback to menu if cancelled or fails
      }
    }
    setShowMenu(!showMenu);
  };

  const copyToClipboard = async () => {
    try {
      const shareStr = `${title}\n${text}\n${url}`;
      await navigator.clipboard.writeText(shareStr);
      showToast('Link & details copied!', 'success');
      setShowMenu(false);
    } catch (err) {
      showToast('Copy failed', 'error');
    }
  };

  // Robust URL Construction
  const encodedUrl = encodeURIComponent(url);
  const encodedText = encodeURIComponent(`${title}: ${text}`);
  const whatsappUrl = `https://api.whatsapp.com/send?text=${encodedText}%20${encodedUrl}`;
  const twitterUrl = `https://twitter.com/intent/tweet?text=${encodedText}&url=${encodedUrl}`;
  const facebookUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`;

  const variants = {
    icon: `w-10 h-10 bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 rounded-xl ${className}`,
    ghost: `text-gray-500 hover:text-blue-500 text-sm ${className}`,
    outline: `border border-white/10 text-gray-400 hover:border-blue-500 hover:text-white px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest ${className}`,
    full: `bg-blue-600 text-white hover:bg-blue-700 px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-500/20 ${className}`
  };

  return (
    <div className="relative inline-block" ref={menuRef}>
      <button 
        onClick={handleShareTrigger} 
        className={`flex items-center justify-center transition-all active:scale-95 shrink-0 ${variants[variant]}`}
      >
        <Share2 size={16} className={`${!iconOnly && variant !== 'icon' ? 'mr-3' : ''}`} />
        {!iconOnly && variant !== 'icon' && <span>Share Node</span>}
      </button>

      {showMenu && (
        <div className="absolute bottom-full mb-4 right-0 w-52 bg-[#0a0a0a] border border-white/10 rounded-3xl shadow-2xl p-2 z-[100] animate-in slide-in-from-bottom-2">
          <div className="flex justify-between items-center px-4 py-3 border-b border-white/5 mb-1">
            <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Channels</span>
            <button onClick={() => setShowMenu(false)} className="text-gray-500 hover:text-white"><CloseIcon size={12} /></button>
          </div>
